contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public {
        address beforeOwner = c.owner();
        require(beforeOwner != address(0), "owner must be initialized");

        bool reverted;
        bool success;
        try c.setOwner(newOwner) returns (bool ret) {
            reverted = false;
            success = ret;
        } catch {
            reverted = true;
        }

        address afterOwner = c.owner();

        if (msg.sender == beforeOwner) {
            assert(!reverted && afterOwner == newOwner && success == true);
        } else {
            assert(reverted && afterOwner == beforeOwner);
        }
    }
}

