contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        // Record the initial owner (must be the test contract that deployed c)
        address initialOwner = c.owner();

        // Attempt the setOwner call from the test contract (the admin)
        bool reverted;
        bool returned;
        try c.setOwner(newOwner) returns (bool success) {
            reverted = false;
            returned = success;
        } catch {
            reverted = true;
            returned = false;
        }

        // Read the final owner after the call
        address finalOwner = c.owner();

        // General rule:
        // - The initial owner must be the test contract (the deployer/admin).
        // - If the call reverts, the owner must remain the initial owner.
        // - If the call succeeds, it must return true and the owner must equal newOwner.
        assert(
            initialOwner == address(this) &&
            (reverted ? finalOwner == initialOwner : (returned && finalOwner == newOwner))
        );
    }
}

