    function run(address newOwner) public {
        // The test contract is the admin because it deployed C.
        address beforeOwner = c.owner();

        // Admin calls setOwner. Since the test contract is the admin, it must succeed.
        bool success = c.setOwner(newOwner);

        // The call must return true, the owner must be changed to newOwner,
        // and the owner must differ from beforeOwner unless newOwner happened to be beforeOwner (which is allowed but not required by the rule? We assert exact equality to newOwner).
